import {validateMessage} from './validation.js';

// spec: specs/hal-engine-websocket-protocol/spec.md#list-sessions-validation
it('accepts list_sessions paging values and rejects malformed fields', () => {
  const before = {sessionId: 'session-1', updatedAt: '2026-10-28T10:00:00.000Z'};

  expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  for (const limit of [0, 1, 201]) {
    for (const updatedAt of [before.updatedAt, 0]) {
      const cursor = {...before, updatedAt};
      expect(validateMessage({type: 'list_sessions', limit, before: {...cursor, extra: true}, userId: 'other'})).toEqual({
        valid: true,
        data: {type: 'list_sessions', limit, before: cursor},
      });
    }
  }
  for (const limit of [-1, 1.5, '10', null, Infinity, NaN]) {
    expect(validateMessage({type: 'list_sessions', limit})).toEqual({valid: false, error: expect.stringContaining('limit')});
  }
  for (const cursor of [null, [], 'yesterday', {}, {...before, sessionId: ''}, {...before, sessionId: 's'.repeat(129)}, {...before, updatedAt: 'not a date'}, {...before, updatedAt: Infinity}, {...before, updatedAt: 1e20}]) {
    expect(validateMessage({type: 'list_sessions', before: cursor})).toEqual({valid: false, error: expect.stringContaining('before')});
  }
});
EOF
 timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsValidation.test.ts --runInBand"

